<?php
declare(strict_types=1);

/**
 * MRL Pick Submission Confirmation Installer
 *
 * VERSION: v001
 * CREATED: 8/30/2026
 *
 * Installs:
 *   - team.php v039
 *   - submit-team-picks.php v012
 *
 * Behavior:
 *   - Intended to be uploaded to public_html and opened in a browser.
 *   - Creates timestamped backups of existing target files before replacement.
 *   - Verifies SHA-256 after writing each file.
 *   - Does not modify the database.
 */

date_default_timezone_set('America/New_York');

$installerVersion = 'v001';
$baseDir = __DIR__;

$files = [
    'team.php' => [
        'label' => 'team.php v039',
        'data' => '',
        'sha256' => '2e89ba91bed8a23265e278a2e09ba635b75135e623b3e9f2ad4bdd1fd82cba75',
    ],
    'submit-team-picks.php' => [
        'label' => 'submit-team-picks.php v012',
        'data' => '',
        'sha256' => 'd54d4a8f731ba3a86b334c0bda93bbf5d1efa9726f3259a1b0e88049e71db7b7',
    ],
];

function h(string $value): string
{
    return htmlspecialchars($value, ENT_QUOTES, 'UTF-8');
}

function file_status(string $path, string $expectedSha): array
{
    if (!is_file($path)) {
        return [
            'exists' => false,
            'sha256' => '',
            'matches' => false,
        ];
    }

    $sha = hash_file('sha256', $path);
    return [
        'exists' => true,
        'sha256' => $sha ?: '',
        'matches' => is_string($sha) && hash_equals($expectedSha, $sha),
    ];
}

$messages = [];
$installSucceeded = null;

if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['install'])) {
    $timestamp = date('Ymd_His');
    $allOk = true;

    foreach ($files as $filename => $info) {
        $targetPath = $baseDir . DIRECTORY_SEPARATOR . $filename;
        $decoded = base64_decode((string)$info['data'], true);

        if ($decoded === false) {
            $messages[] = [
                'type' => 'error',
                'text' => "Unable to decode embedded file: {$filename}",
            ];
            $allOk = false;
            continue;
        }

        if (is_file($targetPath)) {
            $backupPath = $targetPath . '.backup_' . $timestamp;

            if (!@copy($targetPath, $backupPath)) {
                $messages[] = [
                    'type' => 'error',
                    'text' => "Backup failed for {$filename}. Installation stopped for this file.",
                ];
                $allOk = false;
                continue;
            }

            $messages[] = [
                'type' => 'ok',
                'text' => "Backup created: " . basename($backupPath),
            ];
        }

        $tempPath = $targetPath . '.mrl_install_tmp';

        if (@file_put_contents($tempPath, $decoded, LOCK_EX) === false) {
            $messages[] = [
                'type' => 'error',
                'text' => "Unable to write temporary file for {$filename}.",
            ];
            $allOk = false;
            @unlink($tempPath);
            continue;
        }

        $writtenSha = hash_file('sha256', $tempPath);
        if (!is_string($writtenSha) || !hash_equals((string)$info['sha256'], $writtenSha)) {
            $messages[] = [
                'type' => 'error',
                'text' => "Verification failed before installing {$filename}.",
            ];
            $allOk = false;
            @unlink($tempPath);
            continue;
        }

        if (!@rename($tempPath, $targetPath)) {
            if (!@copy($tempPath, $targetPath)) {
                $messages[] = [
                    'type' => 'error',
                    'text' => "Unable to replace {$filename}.",
                ];
                $allOk = false;
                @unlink($tempPath);
                continue;
            }
            @unlink($tempPath);
        }

        $finalSha = hash_file('sha256', $targetPath);
        if (!is_string($finalSha) || !hash_equals((string)$info['sha256'], $finalSha)) {
            $messages[] = [
                'type' => 'error',
                'text' => "Final verification failed for {$filename}.",
            ];
            $allOk = false;
            continue;
        }

        $messages[] = [
            'type' => 'ok',
            'text' => "Installed and verified: " . (string)$info['label'],
        ];
    }

    $installSucceeded = $allOk;
}

$statuses = [];
foreach ($files as $filename => $info) {
    $statuses[$filename] = file_status(
        $baseDir . DIRECTORY_SEPARATOR . $filename,
        (string)$info['sha256']
    );
}
?>
<!doctype html>
<html lang="en">
