<body>
<div class="wrap">
    <div class="panel">
        <h1>MRL Pick Submission Confirmation Installer</h1>
        <div class="sub">Installer <?php echo h($installerVersion); ?> — installs team.php v039 and submit-team-picks.php v012</div>

        <p>This installer will replace the two files in this same folder. Before replacing an existing file, it creates a timestamped backup.</p>

        <?php if ($installSucceeded !== null): ?>
            <div class="result">
                <strong class="<?php echo $installSucceeded ? 'ok' : 'error'; ?>">
                    <?php echo $installSucceeded ? '✓ Installation completed successfully.' : 'Installation completed with one or more errors.'; ?>
                </strong>
                <?php foreach ($messages as $message): ?>
                    <div class="<?php echo h($message['type']); ?>" style="margin-top:8px;">
                        <?php echo h($message['text']); ?>
                    </div>
                <?php endforeach; ?>
            </div>
        <?php endif; ?>

        <?php foreach ($files as $filename => $info): ?>
            <?php $status = $statuses[$filename]; ?>
            <div class="file">
                <strong><?php echo h((string)$info['label']); ?></strong><br>
                <?php if (!$status['exists']): ?>
                    <span class="muted">Current target file not found. It will be created.</span>
                <?php elseif ($status['matches']): ?>
                    <span class="ok">✓ This version is already installed and verified.</span>
                <?php else: ?>
                    <span class="muted">Existing file found. It will be backed up before replacement.</span>
                <?php endif; ?>
            </div>
        <?php endforeach; ?>

        <form method="post">
            <button type="submit" name="install" value="1">Install / Update Files</button>
        </form>

        <p class="muted" style="margin-top:20px;">
            After a successful installation, you can delete this installer from public_html.
        </p>
    </div>
</div>
</body>
</html>
